        int[] stack = new int[n];
        int top = 0;

        // 用栈模拟原序列的全部消除
        for (int i = 0; i < n; i++) {
            if (top > 0 && stack[top - 1] == c[i]) {
                top--;
            } else {
                stack[top++] = c[i];
            }
        }

        int m = top;

        // 原本已经可以消除的次数
        int base = (n - m) / 2;

        // 若已经全部消完，插入一个物品也不能产生新消除
        if (m == 0) {
            return base;
        }

        int[] reduced = Arrays.copyOf(stack, m);

